#include <stdio.h>

int main() {
    int limit = 30;
    int composite[31] = {0};
    for (int i = 2; i * i <= limit; i++) {
        if (!composite[i]) {
            for (int j = i * i; j <= limit; j += i) {
                composite[j] = 1;
            }
        }
    }
    for (int i = 2; i <= limit; i++) {
        if (!composite[i]) {
            printf("%d ", i);
        }
    }
    printf("\n");
    return 0;
}
